        device_id: 'my-device',
    };
    const defaultProps = {
        device: baseDevice,
    };
    const getComponent = (props = {}) => <DeviceDetails {...defaultProps} {...props} />;
    // 14.03.2022 16:15
    const now = 1647270879403;
    jest.useFakeTimers();

    beforeEach(() => {
